(function(){
  var script = document.createElement('script');
  script.src = '/js/live2d/live2d.min.js';
  script.onload = function(){
    L2Dwidget.init({
      model: {
        jsonPath: '/js/live2d/models/haru/haru.model.json',
        scale: 1
      },
      display: {
        position: 'right',
        width: 150,
        height: 300,
        hOffset: 0,
        vOffset: -20
      },
      mobile: { show: true, scale: 0.5 },
      react: { opacityDefault: 0.7, opacityOnHover: 0.9 }
    });
  };
  document.body.appendChild(script);
})();